-- MP-0052: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin if not exists(select 1 from public.entities where slug='government' and type='bloc') then raise exception 'MP-0052: missing party parent'; end if; if exists(select 1 from public.entities where slug='star' and (type <> 'party' or owner_id is not null or parent_id is distinct from (select id from public.entities where slug='government'))) then raise exception 'MP-0052: party identity conflict'; end if; end $$;

insert into public.entities (type,parent_id,slug,name,short_name,bloc,description,profile_checked_at,profile_sources) select 'party',parent.id,'star','Parti Solidariti Tanah Airku','STAR','government','A separate government-supporting Sabah party. It left GRS in October 2025 and is not presented as a current GRS component.','2026-11-10','[{"label": "STAR · GRS exit, October 2025", "url": "https://www.malaysiakini.com/news/756847"}, {"label": "STAR · separate Sabah support, April 2026", "url": "https://www.thestar.com.my/news/nation/2026/04/16/sabah-star-defends-kitingan-agency-role"}, {"label": "Federal government-bloc context · March 2026", "url": "https://theedgemalaysia.com/node/794820"}, {"label": "SPR · current registered party emblems", "url": "https://www.spr.gov.my/parti-parti-yang-berdaftar/"}]'::jsonb from public.entities parent where parent.slug='government' and parent.type='bloc' on conflict (slug) do nothing;

do $$ begin
 if not exists(select 1 from public.entities where slug='gabungan-rakyat-sabah' and type='alliance') then raise exception 'MP-0052: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='government' and type='bloc') then raise exception 'MP-0052: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='star' and type='party') then raise exception 'MP-0052: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('jonathan-yasin','jeffrey-kitingan','riduan-rubin') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0052: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('ranau','keningau','tenom') and slug not in ('jonathan-yasin','jeffrey-kitingan','riduan-rubin')) then raise exception 'MP-0052: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0052:%' and (m.source_type <> 'editorial' or e.slug not in ('jonathan-yasin','jeffrey-kitingan','riduan-rubin') or m.import_key not like 'MP-0052:' || e.slug || ':%')) then raise exception 'MP-0052: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'jonathan-yasin','Jonathan Yasin','government','Member of the Dewan Rakyat','Ranau','Sabah','Jonathan Yasin represents Ranau, Sabah, in the Dewan Rakyat. Parliament records affiliation with Gabungan Rakyat Sabah (GRS).','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4218','/portraits/jonathan-yasin.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P179.png','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4218"}, {"label": "GRS MPs · current representation, 9 January 2026", "url": "https://gagasanrakyat.my/empat-kerusi-parlimen-sabah-kekal-mahkamah-persekutuan-tolak-permohonan-bersatu/"}]'::jsonb from public.entities parent where parent.slug='gabungan-rakyat-sabah' and parent.type='alliance' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'jeffrey-kitingan','Jeffrey Kitingan','government','Member of the Dewan Rakyat; President of STAR','Keningau','Sabah','Jeffrey Kitingan represents Keningau, Sabah, in the Dewan Rakyat. Current role: Member of the Dewan Rakyat; President of STAR. Affiliated with STAR. STAR is separate from GRS following its October 2025 exit.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4219','/portraits/jeffrey-kitingan.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P180.png','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4219"}, {"label": "STAR · coalition exit, 2 October 2025", "url": "https://www.malaysiakini.com/news/756847"}, {"label": "STAR · current president and separate Sabah government support, 16 April 2026", "url": "https://www.thestar.com.my/news/nation/2026/04/16/sabah-star-defends-kitingan-agency-role"}, {"label": "Federal government-bloc context · 3 March 2026", "url": "https://theedgemalaysia.com/node/794820"}]'::jsonb from public.entities parent where parent.slug='star' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'riduan-rubin','Riduan Rubin','government','Member of the Dewan Rakyat','Tenom','Sabah','Riduan Rubin represents Tenom, Sabah, in the Dewan Rakyat. An independent MP supporting the federal government. KDM affiliation is reported separately; Parliament retains the independent label.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4220','/portraits/riduan-rubin.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P181.jpg','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4220"}, {"label": "Independent · government-bloc context, 3 March 2026", "url": "https://theedgemalaysia.com/node/794820"}, {"label": "KDM affiliation reported separately · 15 August 2026", "url": "https://www.malaysiakini.com/news/782229"}]'::jsonb from public.entities parent where parent.slug='government' and parent.type='bloc' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('jonathan-yasin','jeffrey-kitingan','riduan-rubin') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0052: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0052:jonathan-yasin:ranau-hospital-patient-support','Continue the reported support for bedridden Hospital Ranau patients','Health','in_progress',null,null,null,null,'2026-01-19','https://www.borneodailybulletin.com/jonathan-perkukuh-inisiatif-kebajikan-pembangunan-rakyat-ranau/','Jonathan’s constituency welfare report states that its free-treatment support initiative for bedridden hospital patients remained active.','A January activity report, not a verified entitlement for every patient. No independently audited beneficiary count, expenditure total, completion target or later continuation record was established.','2026-11-10','editorial',false from public.entities e where e.slug='jonathan-yasin' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0052:riduan-rubin:tenom-flood-relief-2026','Deliver food and essentials to Tenom flood-relief centres','Social Welfare','achieved',null,null,null,null,'2026-02-28','https://www.bernama.com/en/general/news.php?id=2528698','Riduan’s team reported initial deliveries to Melalap and Kemabong relief centres, with partner agencies and youth volunteers, plus water supplies for Kuala Tomani frontline services.','Achieved covers the reported initial relief deliveries. It does not claim all affected families were served, that flooding ended or that the MP alone delivered the response.','2026-11-10','editorial',false from public.entities e where e.slug='riduan-rubin' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

commit;
